The following sample script uses the SDK for JavaScript in Node.js, as well as the opensearch-js
client for JavaScript, to create encryption, network, and data access policies, create a matching
collection, create an index, and index some sample data.
To install the required dependencies, run the following commands:
npm i aws-sdk
npm i aws4
npm i @opensearch-project/opensearch
Within the script, replace the Principal element with the Amazon Resource Name (ARN) of the
user or role that's signing the request. You can also optionally modify the region.
var AWS = require('aws-sdk');
var aws4 = require('aws4');
var {
Client,
Connection
} = require("@opensearch-project/opensearch");
var {
OpenSearchServerlessClient,
CreateSecurityPolicyCommand,
CreateAccessPolicyCommand,
CreateCollectionCommand,
BatchGetCollectionCommand
} = require("@aws-sdk/client-opensearchserverless");
var client = new OpenSearchServerlessClient();
async function execute() {
await createEncryptionPolicy(client)
